function placeDebug(x,y){const w=debug.offsetWidth,h=debug.offsetHeight;debug.style.left=Math.max(8,Math.min(x,innerWidth-w-8))+"px";debug.style.top=Math.max(8,Math.min(y,innerHeight-h-8))+"px";debug.style.bottom="auto";}
