grip.addEventListener("pointerdown",e=>{if(e.button!==0)return;const b=debug.getBoundingClientRect();dragging=[e.clientX-b.left,e.clientY-b.top];grip.setPointerCapture(e.pointerId);e.preventDefault()});
grip.addEventListener("pointermove",e=>{if(dragging)placeDebug(e.clientX-dragging[0],e.clientY-dragging[1])});
