mini.onclick=()=>{const collapsed=debug.classList.toggle("mini");mini.textContent=collapsed?"+":"−";mini.setAttribute("aria-label",collapsed?"Expand developer panel":"Collapse developer panel");const b=debug.getBoundingClientRect();placeDebug(b.left,b.top)};
